/* Personal imports stay in IndexedDB on this browser. No book/audio upload,
 * no remote audio URL fetching, no executable book-source rules. */
const jpPublicWordCount=jpWords.length,jpPrivateAudio=new Map();let jpImporting=false;
function jpPrivateDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('learning-japanese-private',1);r.onupgradeneeded=()=>{r.result.createObjectStore('words',{keyPath:'id'});r.result.createObjectStore('audio',{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function jpPrivateRead(store){const db=await jpPrivateDB();return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly'),r=tx.objectStore(store).getAll();let data=[];r.onsuccess=()=>data=r.result;tx.oncomplete=()=>{db.close();resolve(data);};tx.onerror=()=>{db.close();reject(tx.error);};});}
async function jpPrivateWrite(words,audio){const db=await jpPrivateDB();return new Promise((resolve,reject)=>{const tx=db.transaction(['words','audio'],'readwrite');const owner=accountUser?.id||'guest';for(const w of words)tx.objectStore('words').put({...w,wordId:w.id,id:owner+':'+w.id,owner});for(const a of audio)tx.objectStore('audio').put({...a,wordId:a.id,id:owner+':'+a.id,owner});tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>{db.close();reject(tx.error);};});}
async function jpLoadPrivate(){try{const owner=accountUser?.id||'guest',rawWords=await jpPrivateRead('words'),rawAudio=await jpPrivateRead('audio'),words=rawWords.filter(w=>(w.owner||'guest')===owner).map(w=>({...w,id:w.wordId||w.id})),audio=rawAudio.filter(a=>(a.owner||'guest')===owner).map(a=>({...a,id:a.wordId||a.id}));jpWords.splice(jpPublicWordCount);for(const old of jpPrivateAudio.values())URL.revokeObjectURL(old.url);jpPrivateAudio.clear();for(const w of words){if(typeof w.id!=='string'||!w.id.startsWith('personal-')||!w.word||!w.meaning)continue;const index=jpWords.findIndex(x=>x.id===w.id);if(index>=0)jpWords[index]=w;else jpWords.push(w);}for(const a of audio){if(!(a.blob instanceof Blob)||a.blob.size>5*1024*1024)continue;const old=jpPrivateAudio.get(a.id);if(old)URL.revokeObjectURL(old.url);jpPrivateAudio.set(a.id,{url:URL.createObjectURL(a.blob),name:a.name});}if(view==='japanese')render();}catch{jpWorkspaceMessage='当前浏览器暂时无法读取个人词书。公共词书仍可学习。';}}
function jpAudioSource(text,id){const own=jpPrivateAudio.get(id);if(own)return {file:own.url,personal:true,name:own.name};return jpAudioManifest[text]||jpAudioManifest[jpWords.find(w=>w.id===id)?.reading]||null;}
function jpPlayAudio(text,id){const source=jpAudioSource(text,id);if(source){if(jpAudioPlaying)jpAudioPlaying.pause();jpAudioPlaying=new Audio(source.file);jpAudioPlaying.play().catch(()=>toast('录音未能播放。请点击词条中的播放器重试，或检查浏览器的音频权限。'));}else speakJapanese(text);}
const jpMediaBeforeBody=jpWordBody;jpWordBody=function(w){const source=jpAudioSource(w.word,w.id);let html=jpMediaBeforeBody(w).replace('data-jp="speak" data-text="'+esc(w.word)+'"','data-jp="speak" data-word-id="'+esc(w.id)+'" data-text="'+esc(w.word)+'"').replace('>听单词</button>',source?'>播放录音</button>':'>合成读音</button>');if(source)html+=`<section class="jp-native-audio"><h3>${source.personal?'个人导入音频':'授权真人录音'}</h3><audio controls preload="metadata" src="${esc(source.file)}"></audio><p class="small-note">${source.personal?'只存本机 / 不公开、不上传。':`${esc(source.artist)} / ${esc(source.license)} / <a href="${esc(source.source)}" target="_blank" rel="noopener noreferrer">原录音与许可</a>`}</p></section>`;else html+='<p class="small-note">本词暂无随站录音，可使用设备日语合成音或导入自己的录音。</p>';return html;};
jpSpeechNote=function(){return '<p class="small-note jp-speech-note">部分词与假名有公开授权的真人录音。完整例句和未覆盖词使用设备日语合成语音；没有日语音色时会提示。个人词书音频只在当前浏览器保存。</p>';};
const jpPrivateWordHTML=jpWordHTML;jpWordHTML=function(){const w=jpWord(jpWordId);let html=jpPrivateWordHTML();if(w?.custom)html=html.replace('data-level="'+esc(w.level)+'"','data-level="个人词书"').replace('回到 '+esc(w.level)+' 词书','回到个人词书');return w?html+`<section class="jp-section"><h2>导入这个词的个人音频</h2><label for="jp-personal-audio">选择你可供个人使用的 MP3、WAV、OGG 或 M4A，单个不超过 5 MB</label><input id="jp-personal-audio" type="file" data-word-id="${w.id}" accept=".mp3,.wav,.ogg,.m4a"><p class="small-note">录音存本机，不会发布到网站，也不会随账户同步。换设备需要重新导入。</p></section>`:html;};
const jpBeforeBookCards=jpBookCards;jpBookCards=function(){const words=jpWords.filter(w=>w.custom);return jpBeforeBookCards()+(words.length?`<button class="jp-book jp-personal-book" data-jp="book" data-level="个人词书"><span class="jp-book-level">我的</span><h3>个人导入词书</h3><p>仅本机保存 / ${words.length} 词</p><span>${words.filter(w=>jpStudyState.records[w.id]).length} 词已学</span></button>`:'');};
const jpBeforeBook=jpBookHTML;jpBookHTML=function(){if(jpBookLevel!=='个人词书')return jpBeforeBook();const words=jpWords.filter(w=>w.custom);return `${jpHeader('个人导入词书','MY WORDBOOK')}<p>导入内容仅保存在本浏览器，不会发布。记忆记录仍可随个人账户同步，其他设备需自行导入同一份原文件。</p><button class="primary" data-jp="start" data-mode="new" data-level="个人词书">学习个人词书</button>${jpWordsList(words)}`;};
const jpBeforeSessionStart=jpStartSession;jpStartSession=function(mode,level){if(level!=='个人词书'){jpBeforeSessionStart(mode,level);return;}if(jpSessionActive()){jpOpen('session');toast('继续未完成的一轮；完成后可切换词书。');return;}const count=Math.max(0,jpStudyState.goal-jpToday().learned.length),words=jpWords.filter(w=>w.custom&&!jpStudyState.records[w.id]).slice(0,count);if(!words.length){toast(count?'个人词书的新词已学完。':'今天的新词计划已完成。');return;}jpStudyState.session={mode:'new',level:'个人词书',day:jpDay(),queue:words.map(w=>w.id),index:0,revealed:false,graded:false,rating:null,started:Date.now()};jpSave();jpOpen('session');};
function jpParseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;if(rows.length>5001||cell.length>10000)throw Error('词表过大或单元格过长，请分成每次不超过 5000 词。');}if(quoted)throw Error('CSV 引号没有正确闭合，请检查导出文件。');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);const heads=rows.shift()||[];return rows.map(r=>Object.fromEntries(heads.map((h,i)=>[h.trim(),r[i]||''])));}
function jpImportField(row,names,max=1500){const v=names.map(n=>row[n]).find(x=>x!==undefined&&x!==null);return String(Array.isArray(v)?v.filter(x=>typeof x==='string').join('；'):typeof v==='string'||typeof v==='number'?v:'').trim().slice(0,max);}
async function jpNormalizeImport(rows){if(!Array.isArray(rows)||!rows.length)throw Error('没有找到词表。请参考 CSV 模板，或使用 JSON 数组。');if(rows.length>5000)throw Error('每次最多导入 5000 词，请分批导出。');const result=[];for(const r of rows){if(!r||typeof r!=='object')continue;const word=jpImportField(r,['word','spell','expression','单词','日语','词条','词汇'],100),reading=jpImportField(r,['reading','pron','kana','假名','读音','读法'],100),meaning=jpImportField(r,['meaning','meanings','excerpt','definition','释义','词义','中文','解释'],500);if(!word||!reading||!meaning)throw Error('每条词都需要单词、假名和释义。请核对列名或 JSON 字段。');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(word+'\0'+reading)),id='personal-'+[...new Uint8Array(digest)].slice(0,10).map(n=>n.toString(16).padStart(2,'0')).join('');result.push({id,word,reading,meaning,level:jpImportField(r,['level','等级'],10)||'自选',pos:jpImportField(r,['pos','词性'],50)||'导入词条',topic:'个人词书',example:jpImportField(r,['example','日文例句','例句']),translation:jpImportField(r,['translation','例句译文','翻译']),note:jpImportField(r,['note','备注','注释'])||'这是你的个人导入词条。',audioName:jpImportField(r,['audio','音频','audioFilename'],200),custom:true});}return [...new Map(result.map(w=>[w.id,w])).values()];}
async function jpImportFile(file){if(!file||jpImporting)return;jpImporting=true;jpWorkspaceMessage='正在读取个人词书…';const status=$('jp-import-status');if(status)status.textContent=jpWorkspaceMessage;try{if(file.size>50*1024*1024)throw Error('文件超过 50 MB，请拆分后导入。');let rows,zip=null;if(/\.zip$/i.test(file.name)){zip=await JSZip.loadAsync(await file.arrayBuffer());const entries=Object.values(zip.files).filter(f=>!f.dir);if(entries.length>1000||entries.reduce((n,f)=>n+(f._data?.uncompressedSize||0),0)>80*1024*1024)throw Error('压缩包解压后过大，请拆分后导入。');const tables=entries.filter(f=>/\.(json|csv)$/i.test(f.name)),table=tables.find(f=>/(?:^|\/)(?:words|wordbook)\.(json|csv)$/i.test(f.name))||tables[0];if(!table||table._data?.uncompressedSize>5*1024*1024)throw Error('压缩包中需要一个不超过 5 MB 的 CSV 或 JSON 词表。');const text=await table.async('text');rows=/\.csv$/i.test(table.name)?jpParseCSV(text):JSON.parse(text);}else{if(file.size>5*1024*1024)throw Error('词表超过 5 MB，请拆分后导入。');const text=await file.text();rows=/\.csv$/i.test(file.name)?jpParseCSV(text):JSON.parse(text);}if(!Array.isArray(rows))rows=rows.words||rows.entries;const words=await jpNormalizeImport(rows),audio=[];for(const w of words){if(!w.audioName||!zip)continue;if(/^(?:[a-z]+:|\/\/)/i.test(w.audioName))continue;const f=zip.file(w.audioName);if(!f||! /\.(mp3|wav|ogg|m4a)$/i.test(f.name)||f._data?.uncompressedSize>5*1024*1024)continue;const ext=f.name.split('.').pop().toLowerCase(),blob=new Blob([await f.async('arraybuffer')],{type:{mp3:'audio/mpeg',wav:'audio/wav',ogg:'audio/ogg',m4a:'audio/mp4'}[ext]});if(blob.size<=5*1024*1024)audio.push({id:w.id,blob,name:w.audioName});}await jpPrivateWrite(words,audio);await jpLoadPrivate();jpWorkspaceMessage='已在本机保存 '+words.length+' 个词、'+audio.length+' 段个人音频。可在“词书 → 个人导入词书”中打开。';render();}catch(e){jpWorkspaceMessage='未完成导入：'+(e.message||'请检查文件格式。')+' 原有记录没有删除。';render();}finally{jpImporting=false;}}
function jpTemplateDownload(){const csv='\uFEFF单词,假名,释义,词性,日文例句,例句译文,备注,音频\r\n猫,ねこ,猫,名词,猫がいます。,有一只猫。,个人词条示例,\r\n',blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='日语个人词书模板.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-jp="speak"]');if(b){e.preventDefault();e.stopImmediatePropagation();jpPlayAudio(b.dataset.text,b.dataset.wordId);}},true);
document.addEventListener('click',e=>{if(e.target.closest('[data-jp="import-template"]'))jpTemplateDownload();});
document.addEventListener('change',async e=>{if(e.target.id==='jp-import-file')jpImportFile(e.target.files[0]);if(e.target.id==='jp-personal-audio'){const f=e.target.files[0],id=e.target.dataset.wordId;if(!f||!jpWord(id))return;if(f.size>5*1024*1024||! /\.(mp3|wav|ogg|m4a)$/i.test(f.name)){toast('请选择不超过 5 MB 的 MP3、WAV、OGG 或 M4A。');return;}try{await jpPrivateWrite([],[{id,blob:f,name:f.name}]);await jpLoadPrivate();toast('个人音频已保存在本机。');}catch{toast('当前浏览器未能保存音频，请检查存储权限。');}}});
const jpSessionStartBeforePause=jpStartSession;
jpStartSession=function(mode='new',level=jpStudyState.level){const key=mode+':'+level,s=jpStudyState.session;jpStudyState.pausedSessions=jpStudyState.pausedSessions||{};if(jpSessionActive()&&(s.mode!==mode||s.level!==level)){jpStudyState.pausedSessions[s.mode+':'+s.level]=s;jpStudyState.session=null;}const saved=jpStudyState.pausedSessions[key];if(!jpSessionActive()&&saved&&saved.index<saved.queue.length){jpStudyState.session=saved;delete jpStudyState.pausedSessions[key];jpSave();jpOpen('session');return;}jpSessionStartBeforePause(mode,level);};
document.addEventListener('click',e=>{if(e.target.closest('[data-jp="resume-session"]'))jpOpen('session');});
const jpHomeBeforeStudy=hubHome;hubHome=function(){const total=state.completed.length+Object.entries(hubState.completed).filter(([k])=>k!=='japanese').reduce((n,[,v])=>n+v.length,0)+jpStudyState.lessonsDone.length+pythonLessons.filter((_,i)=>pythonPassed(i)).length;return jpHomeBeforeStudy().replace(/<span><b>\d+<\/b> 已完成<\/span>/,'<span><b>'+total+'</b> 已完成</span>');};
jpLoadPrivate();
render();
